import React from 'react';
import { useNavigate } from 'react-router-dom';
import useLogin from './hooks/useLogin';
import { Input } from './components/ui/input';

function Login() {

    const navigate = useNavigate();

  return (
    <div className="w-full h-screen flex flex-col items-center justify-center" style={{ backgroundColor: '#368CE7' }}>
         <h2 className="text-5xl font-semibold text-center text-white mb-4">
          Gabes Pomo
        </h2>
      <div className="p-8 rounded-lg shadow-lg w-full max-w-sm bg-white bg-opacity-20">

        {/* Email Input */}
        <div className="mb-4">
          <Input
            type="email"

            placeholder="email@gmail.com"
          />
        </div>

        {/* Password Input */}
        <div className="mb-6">
          <Input
            type="password"
            className="w-full p-2 bg-white bg-opacity-20 rounded-md text-white placeholder-white outline-none"
            placeholder="password"
          />
        </div>

        {/* Buttons */}
        <button className="w-full bg-white bg-opacity-20 text-white py-2 rounded-md hover:bg-opacity-30 transition" onClick={() => navigate('/home') }>
          Login
        </button>

        <div className="text-center my-4 text-white">or</div>

        <button className="w-full bg-white bg-opacity-20 text-white py-2 rounded-md hover:bg-opacity-30 transition" onClick={() => navigate('/home') }>
          Continue as Guest
        </button>
      </div>
    </div>
  );
}

export default Login;
